def f(a):
    H,W=len(a),len(a[0])
    out=[[0]*W for _ in range(H)]
    cells=[(i,j) for i,r in enumerate(a) for j,x in enumerate(r) if x==5]
    # split into connected components (4-conn of 5s)
    seen=set(); comps=[]
    for c in cells:
        if c in seen: continue
        st=[c]; seen.add(c); comp=[]
