        rs=[i for i,_ in comp]; js=[j for _,j in comp]
        r0,r1,c0,c1=min(rs),max(rs),min(js),max(js)
        # fill interior
        for i in range(r0+1,r1):
            for j in range(c0+1,c1):
                if a[i][j]==0: out[i][j]=2
        # line just above top row
        line_r=r0-1
        if line_r<0: continue
        gapL=c0; gapR=W-1-c1
        if gapL<=gapR:
            # touch left edge: start at col0? use demo3S1 style: start=c0+1, end=W-1
            s,e=c0+1,W-1
        else:
            s,e=0,c1-1
        for j in range(s,e+1): out[line_r][j]=2
    return out
