def solve3(g):
    g=[r[:] for r in g]; H,W=len(g),len(g[0])
    cs=comps(g)
    n=len(cs)
    used=[False]*n
    out=[r[:] for r in g]
    for i in range(n):
        if used[i]: continue
        bi=cs[i]
        rest=[j for j in range(n) if not used[j]]
        partner=None
        for k in rest:
            bk=cs[k]
            # overlapping column ranges and vertical proximity
            s1={c for _,c in bi}; s2={c for _,c in bk}
            if s1&s2 and max([r for r,_ in bi])>=min([r for r,_ in bk])-1:
                partner=k; break
        if partner is not None:
            bj=cs[partner]; used[partner]=True
            rt=[r for r,_ in bi]; ct=[c for _,c in bi]
            ro=[r for r,_ in bj]; co=[c for _,c in bj]
            r0t,r1t=min(rt),max(rt); c0t,c1t=min(ct),max(ct)
            r0b,r1b=min(ro),max(ro); c0b,c1b=min(co),max(co)
            # top box beam: toward the other (other is below and to the RIGHT in our geometry) -> right style [c0+1..W-1]? 
            # But careful: direction toward other horizontally = sign of (c0b - c0t)
            dir = 1 if c0b>c0t else -1
            if dir==1:
                st,sp = c0t+1, W-1  # right style
            else:
                st,sp = 0, c1t-1    # left style
            out[r0t-1][st:sp+1]=[2]*(sp-st+1)
            # bottom box beam: opposite direction
            if dir==1:
                st,sp=0,c1b-1
